-- Paper CSF responses (DOST RO2 QMS 06-F03) transcribed from 2 scanned PDFs
-- 84 responses. Run in Supabase SQL Editor AFTER feedback-forms.sql and feedback-forms-csf.sql.
--
-- 1) Replace YOUR-FORM-SLUG below with your CSF form's slug (the part after /f/ in its link).
--    The form must have form_type = 'csf'. If the slug is wrong, 0 rows are inserted.
-- 2) Mapping: paper SQD1-8 -> sqd1-sqd8, paper Overall Satisfaction (1-5) -> sqd0,
--    "likely to recommend" (1-10) -> recommendScore. Name/age/date/address were blank on the sheets.
-- Review notes: PDF1 p34 (blank form) skipped; PDF1 p4/p18/p21-24/p28 had double or straddling SQD marks;
--    PDF1 p33 had SQD5 unmarked (null); PDF1 p10 General Citizen looked crossed out (Business only).

with form as (
  select id from public.feedback_forms
  where slug = 'YOUR-FORM-SLUG' and form_type = 'csf'
)
insert into public.csf_responses (feedback_form_id, response)
select form.id, v.response
from form,
(values
    ('{"name":"","age":"","sex":"male","address":"","responseDate":"","clientClassifications":["Business"],"clientType":"external","cc1":"cc1_a","cc2":"cc2_a","cc3":"cc3_a","officeUnit":"","employeeName":"","servicesAvailed":[],"sqd":{"sqd0":5,"sqd1":5,"sqd2":5,"sqd3":5,"sqd4":5,"sqd5":5,"sqd6":5,"sqd7":5,"sqd8":5},"comments":"","recommendScore":9}'::jsonb),
